//! Agents test data (.offrails/guides/testing.md#factories-testsappfactoriesrs): valid params
//! through `validate` + `create`, so a test can't build an invalid row. Generated by `cargo offrails generate resource agents name:string description:text`.

/// Valid AgentParams (unique values numbered), for forms and `agent_with`.
pub async fn agent_params(
    db: &sea_orm::DatabaseConnection,
    user: &board::models::User,
) -> board::models::agent::AgentParams {
    let _ = (db, user); // no parent records to create
    static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(1);
    let n = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    board::models::agent::AgentParams {
        name: format!("Name {n}"),
        description: format!("Description {n}, long enough to read."),
    }
}

/// A agent owned by `user`, through `AgentParams::validate` + `agent::create`.
pub async fn agent(
    db: &sea_orm::DatabaseConnection,
    user: &board::models::User,
) -> board::models::agent::Model {
    let params = agent_params(db, user).await;
    agent_with(db, user, params).await
}

/// A agent owned by `user` from these params (they must be valid).
pub async fn agent_with(
    db: &sea_orm::DatabaseConnection,
    user: &board::models::User,
    params: board::models::agent::AgentParams,
) -> board::models::agent::Model {
    let new = params.validate().expect("valid agent params");
    board::models::agent::create(db, user, new)
        .await
        .expect("create agent")
}

/// Reads a agent back through the entity (tests can't call the model-private `find`).
pub async fn reload_agent(
    db: &sea_orm::DatabaseConnection,
    id: i64,
) -> Option<board::models::agent::Model> {
    use sea_orm::EntityTrait;
    board::models::agent::Entity::find_by_id(id)
        .one(db)
        .await
        .expect("reload agent")
}
